// Stage 1: Data Normalization
const item = $input.first().json;

// 1. Email Normalization
const rawEmail = (item.customer_email || '').trim().toLowerCase();

// 2. Phone Normalization (E.164 NANP)
let rawPhone = (item.customer_phone || '').replace(/[^\d+]/g, '');
let cleanPhone = '';
if (rawPhone.startsWith('+')) {
  cleanPhone = rawPhone;
} else if (rawPhone.length === 10) {
  cleanPhone = '+1' + rawPhone;
} else if (rawPhone.length === 11 && rawPhone.startsWith('1')) {
  cleanPhone = '+' + rawPhone;
} else {
  cleanPhone = '+' + rawPhone;
}

// 3. Event and Subfolder Naming
const createDtSafe = (item.create_datetime || '').replace(/[: ]/g, '-');
const eventSubfolder = `${item.appointment_id}_${item.provider_first_name || 'contact'}_${createDtSafe}`;

return {
  json: {
    ...item,
    customer_email: rawEmail,
    customer_phone_normalized: cleanPhone,
    event_subfolder_name: eventSubfolder
  }
};
